import os
import stat
import sys


def count_file(path):
    st = os.stat(path)
    if not stat.S_ISREG(st.st_mode):
        raise OSError("not a regular file")

    with open(path, "r", encoding="utf-8", newline="") as f:
        text = f.read()

    if not text:
        lines = 0
    else:
        lines = text.count("\n")
        if not text.endswith("\n"):
            lines += 1

    words = len(text.split())
    chars = len(text)

