#!/usr/bin/env python3
import json
import os
import stat
import sys


def count_text(text):
    if not text:
        lines = 0
    else:
        lines = text.count("\n")
        if not text.endswith("\n"):
            lines += 1

    words = len(text.split())
    chars = len(text)
    return lines, words, chars


def read_stdin_text():
    stdin = sys.stdin
    if stdin is None:
        raise OSError("standard input is unavailable")

    buffer = getattr(stdin, "buffer", None)
    if buffer is not None:
        data = buffer.read()
    else:
        data = stdin.read()

    if data is None:
        return ""

    if isinstance(data, (bytes, bytearray)):
        return data.decode("utf-8")
    return data


def read_file_text(path):
    if path == "-":
        return read_stdin_text()

    st = os.stat(path)
    if not stat.S_ISREG(st.st_mode):
        raise OSError("not a regular file")

    with open(path, "rb") as f:
        data = f.read()

    return data.decode("utf-8")


def parse_args(argv):
    as_json = False
    files = []

    for arg in argv:
        if arg == "--json":
            as_json = True
        else:
            files.append(arg)

    return as_json, files


def format_table(rows):
    output_rows = list(rows)

    if len(rows) >= 2:
        output_rows.append(
            (
                sum(row[0] for row in rows),
                sum(row[1] for row in rows),
                sum(row[2] for row in rows),
                "total",
            )
        )

    headers = ("lines", "words", "chars")
    widths = [
        max([len(header)] + [len(str(row[i])) for row in output_rows])
        for i, header in enumerate(headers)
    ]

    output = []
    for row in [("lines", "words", "chars", "file"), *output_rows]:
        output.append(
            f"{row[0]:>{widths[0]}}  "
            f"{row[1]:>{widths[1]}}  "
            f"{row[2]:>{widths[2]}}  "
            f"{row[3]}"
        )

    return "\n".join(output) + "\n"


def format_json(rows):
    files = [
        {"file": path, "lines": lines, "words": words, "chars": chars}
        for lines, words, chars, path in rows
    ]

    total = {
        "lines": sum(row[0] for row in rows),
        "words": sum(row[1] for row in rows),
        "chars": sum(row[2] for row in rows),
    }

    return json.dumps({"files": files, "total": total}, indent=2) + "\n"


def main():
    as_json, files = parse_args(sys.argv[1:])

    if not files:
        sys.stderr.write("usage: wordcount.py FILE [FILE ...]\n")
        return 2

    rows = []
    had_error = False

    for path in files:
        try:
            text = read_file_text(path)
            lines, words, chars = count_text(text)
        except Exception:
            sys.stderr.write(f"wordcount.py: cannot read {path}\n")
            had_error = True
        else:
            rows.append((lines, words, chars, path))

    if as_json:
        sys.stdout.write(format_json(rows))
    elif rows:
        sys.stdout.write(format_table(rows))

    return 1 if had_error else 0


if __name__ == "__main__":
    sys.exit(main())
