#!/usr/bin/env python3
import os
import stat
import sys

USAGE = "usage: python logscan.py PATH LEVEL [--at-least] [--limit N]"
LEVEL_RANK = {"INFO": 0, "WARN": 1, "ERROR": 2}


def usage_error():
    sys.stderr.write(USAGE + "\n")
    raise SystemExit(2)


def cannot_open(path):
    sys.stderr.write(f"logscan.py: cannot open {path}\n")
    raise SystemExit(1)


def parse_limit(value):
    try:
        n = int(value)
    except ValueError:
        usage_error()
    if n < 0:
        usage_error()
    return n


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)

    positionals = []
    at_least = False
    limit = None

    i = 0
    while i < len(argv):
        arg = argv[i]

        if arg == "--":
            positionals.extend(argv[i + 1:])
            break

        if arg == "--at-least":
            at_least = True

        elif arg == "--limit":
            if i + 1 >= len(argv):
                usage_error()
            limit = parse_limit(argv[i + 1])
            i += 2
            continue

        elif arg.startswith("--limit="):
            limit = parse_limit(arg.split("=", 1)[1])

        elif arg.startswith("--"):
            usage_error()

        else:
            positionals.append(arg)

        i += 1

    if len(positionals) != 2:
        usage_error()

    path, level_arg = positionals
    level = level_arg.upper()

    if level not in LEVEL_RANK:
        usage_error()

    try:
        st = os.stat(path)
    except (OSError, ValueError):
        cannot_open(path)

    if not stat.S_ISREG(st.st_mode):
        cannot_open(path)

    try:
        f = open(path, "r", encoding="utf-8", newline="")
    except (OSError, ValueError):
        cannot_open(path)

    count = 0
    printed = 0
    target_rank = LEVEL_RANK[level]
    out = sys.stdout.buffer

    with f:
        for line in f:
            fields = line.split()
            if len(fields) >= 3:
                file_level = fields[2]
                rank = LEVEL_RANK.get(file_level)

                if rank is not None and (
                    rank == target_rank or (at_least and rank >= target_rank)
                ):
                    count += 1

                    if limit is None or printed < limit:
                        if line.endswith("\n"):
                            out.write(line.encode("utf-8"))
                        else:
                            out.write((line + "\n").encode("utf-8"))
                        printed += 1

    out.flush()
    sys.stderr.write(f"count={count}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
