"""Operations on sets of integers represented as half-open intervals."""

from collections.abc import Iterable, Sequence
from operator import index

__all__ = ("merge", "insert", "remove", "intersect")

IntervalPair = tuple[int, int]
IntervalSequence = Sequence[int]
IntervalIterable = Iterable[IntervalSequence]


def _normalize(intervals: IntervalIterable) -> list[IntervalPair]:
    """Validate, drop empty intervals, sort, and coalesce touching/overlapping ones."""
    try:
        iterator = iter(intervals)
    except TypeError as exc:
        raise ValueError("intervals must be iterable") from exc

    normalized: list[IntervalPair] = []
    for item in iterator:
        try:
            start, end = item
        except (TypeError, ValueError) as exc:
            raise ValueError("each interval must be a pair of integers") from exc

        try:
            start = index(start)
            end = index(end)
        except TypeError as exc:
            raise ValueError("interval endpoints must be integers") from exc

        if start > end:
            raise ValueError(f"invalid interval ({start}, {end}): start > end")

        if start < end:
            normalized.append((start, end))

    if not normalized:
        return []

    normalized.sort()

    merged: list[IntervalPair] = []
    for start, end in normalized:
        if not merged or start > merged[-1][1]:
            merged.append((start, end))
        elif end > merged[-1][1]:
            merged[-1] = (merged[-1][0], end)

    return merged


def merge(intervals: IntervalIterable) -> list[IntervalPair]:
    """Return the normal form of the union of all intervals."""
    return _normalize(intervals)


def insert(intervals: IntervalIterable, new: IntervalSequence) -> list[IntervalPair]:
    """Return the union of intervals and new, in normal form."""
    normalized_existing = _normalize(intervals)
    normalized_new = _normalize([new])

    if not normalized_new:
        return normalized_existing

    return _normalize(normalized_existing + normalized_new)


def remove(intervals: IntervalIterable, cut: IntervalSequence) -> list[IntervalPair]:
    """Return the integers from intervals that are not in cut, in normal form."""
    normalized_existing = _normalize(intervals)
    normalized_cut = _normalize([cut])

    if not normalized_existing or not normalized_cut:
        return normalized_existing

    cut_start, cut_end = normalized_cut[0]
    result: list[IntervalPair] = []

    for start, end in normalized_existing:
        if end <= cut_start or start >= cut_end:
            result.append((start, end))
            continue

        if start < cut_start:
            result.append((start, cut_start))
        if end > cut_end:
            result.append((cut_end, end))

    return _normalize(result)


def intersect(a: IntervalIterable, b: IntervalIterable) -> list[IntervalPair]:
    """Return the integers that are in both a and b, in normal form."""
    first = _normalize(a)
    second = _normalize(b)

    result: list[IntervalPair] = []
    i = j = 0

    while i < len(first) and j < len(second):
        start = max(first[i][0], second[j][0])
        end = min(first[i][1], second[j][1])

        if start < end:
            result.append((start, end))

        if first[i][1] < second[j][1]:
            i += 1
        elif first[i][1] > second[j][1]:
            j += 1
        else:
            i += 1
            j += 1

    return _normalize(result)
