"""Greedy fully-justified text formatting."""


def justify(text: str, width: int) -> list[str]:
    """
    Justify *text* greedily to lines of *width* characters.

    Whitespace in the input only separates words. A word longer than *width*
    is placed alone on its own line without padding.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines: list[list[str]] = []
    current: list[str] = []
    current_length = 0

    for word in words:
        word_length = len(word)

        if current and current_length + 1 + word_length <= width:
            current.append(word)
            current_length += 1 + word_length
        else:
            if current:
                lines.append(current)
            current = [word]
            current_length = word_length

    if current:
        lines.append(current)

    return [
        _format_line(line, width, index == len(lines) - 1)
        for index, line in enumerate(lines)
    ]


def _format_line(line: list[str], width: int, is_last: bool) -> str:
    if is_last:
        return " ".join(line)

    if len(line) == 1:
        word = line[0]
        if len(word) > width:
            return word
        return word.ljust(width)

    content_length = sum(len(word) for word in line)
    gaps = len(line) - 1
    spaces = width - content_length

    base, extra = divmod(spaces, gaps)

    parts: list[str] = []
    for index, word in enumerate(line):
        parts.append(word)
        if index < gaps:
            gap_spaces = base + (1 if index < extra else 0)
            parts.append(" " * gap_spaces)

    return "".join(parts)
