"""GitHub-flavoured Markdown table formatting."""

__all__ = ["format_table"]

_ALLOWED_ALIGNMENTS = ("left", "right", "center")


def _render_cell(value):
    text = "" if value is None else str(value)
    text = text.replace("|", "\\|")
    text = text.replace("\r\n", "<br>")
    text = text.replace("\n", "<br>")
    return text


def _pad(text, width, alignment):
    extra = width - len(text)

    if alignment == "left":
        return text + " " * extra
    if alignment == "right":
        return " " * extra + text

    left_pad = extra // 2
    return " " * left_pad + text + " " * (extra - left_pad)


def _separator(width, alignment):
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    return ":" + "-" * (width - 2) + ":"


def format_table(rows, headers, align=None) -> str:
    try:
        ncols = len(headers)
    except TypeError as exc:
        raise ValueError("headers must be a non-empty sequence") from exc

    if ncols == 0:
        raise ValueError("headers must be a non-empty sequence")

    try:
        header_texts = tuple(_render_cell(header) for header in headers)
    except TypeError as exc:
        raise ValueError("headers must be a non-empty sequence") from exc

    if len(header_texts) != ncols:
        raise ValueError("headers length changed while iterating")

    if align is None:
        alignments = ("left",) * ncols
    else:
        try:
            align_values = tuple(align)
        except TypeError as exc:
            raise ValueError("align must be None or a sequence of alignments") from exc

        if len(align_values) != ncols:
            raise ValueError("align must have one entry per header")

        for alignment in align_values:
            if alignment not in _ALLOWED_ALIGNMENTS:
                raise ValueError(f"unknown alignment: {alignment!r}")

        alignments = align_values

    widths = [max(3, len(header_text)) for header_text in header_texts]
    rendered_rows = []

    try:
        row_iterator = iter(rows)
    except TypeError as exc:
        raise ValueError("rows must be iterable") from exc

    for row_number, row in enumerate(row_iterator):
        try:
            row_cells = tuple(row)
        except TypeError as exc:
            raise ValueError(f"row {row_number} must be a sequence") from exc

        if len(row_cells) != ncols:
            raise ValueError(
                f"row {row_number} has {len(row_cells)} cells, expected {ncols}"
            )

        rendered_cells = tuple(_render_cell(cell) for cell in row_cells)

        for idx, cell_text in enumerate(rendered_cells):
            if len(cell_text) > widths[idx]:
                widths[idx] = len(cell_text)

        rendered_rows.append(rendered_cells)

    def line(parts):
        return "| " + " | ".join(parts) + " |"

    header_parts = tuple(
        _pad(header_texts[i], widths[i], alignments[i])
        for i in range(ncols)
    )

    separator_parts = tuple(
        _separator(widths[i], alignments[i])
        for i in range(ncols)
    )

    lines = [line(header_parts), line(separator_parts)]

    for rendered_cells in rendered_rows:
        row_parts = tuple(
            _pad(rendered_cells[i], widths[i], alignments[i])
            for i in range(ncols)
        )
        lines.append(line(row_parts))

    return "\n".join(lines)
