"""Dependency-graph topological sorting utilities."""

import heapq
from collections.abc import Iterable, Mapping

__all__ = ["CycleError", "toposort", "levels", "subgraph_order"]


class CycleError(ValueError):
    """Raised when a dependency graph contains a cycle.

    The ``cycle`` attribute is a list of distinct nodes ``[n1, ..., nk]``
    forming a dependency cycle: ``n1`` depends on ``n2``, ..., and ``nk``
    depends on ``n1``.
    """

    def __init__(self, cycle, message=None):
        self.cycle = list(cycle)
        if message is None:
            message = f"Graph contains a cycle: {self.cycle}"
        super().__init__(message)


def _build_graph(graph: Mapping[str, Iterable[str]]) -> tuple[set[str], dict[str, set[str]]]:
    """Return all nodes and a set-based dependency mapping.

    A node is either a key of ``graph`` or appears as a dependency of some key.
    """
    nodes: set[str] = set()
    dependencies: dict[str, set[str]] = {}

    for node, dependency_iterable in graph.items():
        dependency_set = set(dependency_iterable)

        nodes.add(node)
        current = dependencies.get(node, set())
        current.update(dependency_set)
        dependencies[node] = current

        for dependency in dependency_set:
            nodes.add(dependency)
            dependencies.setdefault(dependency, set())

    return nodes, dependencies


def _find_cycle(remaining: set[str], dependencies: dict[str, set[str]]) -> list[str]:
    """Find a cycle among nodes left by Kahn's algorithm.

    Every node in ``remaining`` is assumed to depend on at least one other node
    in ``remaining``.
    """
    position: dict[str, int] = {}
    path: list[str] = []

    node = min(remaining)
    while node not in position:
        position[node] = len(path)
        path.append(node)

        possible_next = dependencies[node] & remaining
        node = min(possible_next)

    return path[position[node]:]


def _toposort_order(nodes: set[str], dependencies: dict[str, set[str]]) -> list[str]:
    """Topologically order an already-normalized graph."""
    if not nodes:
        return []

    dependents: dict[str, set[str]] = {node: set() for node in nodes}
    remaining_count: dict[str, int] = {}

    for node in nodes:
        remaining_count[node] = len(dependencies[node])

    for node in nodes:
        for dependency in dependencies[node]:
            dependents[dependency].add(node)

    available = [node for node, count in remaining_count.items() if count == 0]
    heapq.heapify(available)

    order: list[str] = []

    while available:
        node = heapq.heappop(available)
        order.append(node)

        for dependent in dependents[node]:
            remaining_count[dependent] -= 1
            if remaining_count[dependent] == 0:
                heapq.heappush(available, dependent)

    if len(order) != len(nodes):
        remaining = nodes - set(order)
        raise CycleError(_find_cycle(remaining, dependencies))

    return order


def toposort(graph: Mapping[str, Iterable[str]]) -> list[str]:
    """Return a lexicographically-broken-tie topological ordering of ``graph``.

    Each node appears after all nodes it depends on. If a cycle exists, raise
    ``CycleError``.
    """
    nodes, dependencies = _build_graph(graph)
    return _toposort_order(nodes, dependencies)


def levels(graph: Mapping[str, Iterable[str]]) -> list[list[str]]:
    """Return dependency levels that can be processed in parallel.

    Level 0 contains nodes with no dependencies. Any other node is placed in
    ``1 + max(dependency levels)``. Each level is sorted lexicographically.
    """
    nodes, dependencies = _build_graph(graph)
    order = _toposort_order(nodes, dependencies)

    if not order:
        return []

    node_level: dict[str, int] = {}

    for node in order:
        deps = dependencies[node]
        if deps:
            node_level[node] = 1 + max(node_level[dependency] for dependency in deps)
        else:
            node_level[node] = 0

    result: list[list[str]] = [[] for _ in range(max(node_level.values()) + 1)]
    for node, level in node_level.items():
        result[level].append(node)

    for level in result:
        level.sort()

    return [level for level in result if level]


def subgraph_order(graph: Mapping[str, Iterable[str]], targets: Iterable[str]) -> list[str]:
    """Return the toposort order of nodes needed to build ``targets``.

    ``targets`` may contain duplicates. A target that is not a node of ``graph``
    raises ``KeyError``. Cycles outside the needed subgraph are ignored.
    """
    nodes, dependencies = _build_graph(graph)

    needed: set[str] = set()
    for target in targets:
        try:
            exists = target in nodes
        except TypeError:
            raise KeyError(target) from None

        if not exists:
            raise KeyError(target)

        needed.add(target)

    if not needed:
        return []

    stack = list(needed)
    while stack:
        node = stack.pop()
        for dependency in dependencies[node]:
            if dependency not in needed:
                needed.add(dependency)
                stack.append(dependency)

    restricted_dependencies = {node: dependencies[node] & needed for node in needed}
    return _toposort_order(needed, restricted_dependencies)
