"""Read values from nested JSON-like objects using path strings."""

from collections.abc import Mapping

__all__ = ["PathError", "parse", "get"]


class PathError(LookupError):
    """Error raised for invalid paths or missing values."""

    def __init__(self, message: str | None = None, path: str | None = None):
        if message is None:
            message = ""
        if path is None:
            path = message
        super().__init__(message)
        self.path = path


_MISSING = object()
_NAME_STOP = frozenset({".", "[", "]", '"'})
_DIGITS = frozenset("0123456789")


def _syntax_error(path: str, message: str) -> PathError:
    return PathError(f"invalid path {path!r}: {message}", path)


def _parse_bracket(path: str, i: int, n: int) -> tuple[str | int, int]:
    """Parse [N] or ["..."] starting at path[i] == '['."""
    j = i + 1
    if j >= n:
        raise _syntax_error(path, "unclosed bracket")

    if path[j] == '"':
        k = j + 1
        chars = []
        closed = False

        while k < n:
            ch = path[k]

            if ch == '"':
                closed = True
                k += 1
                break

            if ch == "\\":
                if k + 1 >= n:
                    raise _syntax_error(path, "invalid escape sequence")

                nxt = path[k + 1]
                if nxt == '"' or nxt == "\\":
                    chars.append(nxt)
                    k += 2
                else:
                    raise _syntax_error(path, "invalid escape sequence")
            else:
                chars.append(ch)
                k += 1

        if not closed:
            raise _syntax_error(path, "unclosed quoted key")
        if k >= n or path[k] != "]":
            raise _syntax_error(path, "unclosed bracket")

        return "".join(chars), k + 1

    start = j
    if path[j] == "-":
        j += 1

