class _TrieNode:
    __slots__ = ("children", "word", "weight", "casefolded")

    def __init__(self) -> None:
        self.children: dict[str, "_TrieNode"] = {}
        self.word: str | None = None
        self.weight: float | None = None
        self.casefolded: str | None = None


class Autocomplete:
    def __init__(self) -> None:
        self._root = _TrieNode()
        self._size = 0

    def _node_for(self, casefolded: str) -> _TrieNode | None:
        node = self._root
        for ch in casefolded:
            nxt = node.children.get(ch)
            if nxt is None:
                return None
            node = nxt
        return node

    def _iter_terminal_nodes(self, start: _TrieNode):
        stack = [start]
        while stack:
            node = stack.pop()
            if node.word is not None:
                yield node
            stack.extend(node.children.values())

    def add(self, word: str, weight: float = 1) -> None:
        if not word:
            raise ValueError("word must not be empty")

        casefolded = word.casefold()
        node = self._root

        for ch in casefolded:
            nxt = node.children.get(ch)
            if nxt is None:
                nxt = _TrieNode()
                node.children[ch] = nxt
            node = nxt

        if node.word is None:
            self._size += 1

        node.word = word
        node.weight = weight
        node.casefolded = casefolded

    def delete(self, word: str) -> bool:
        casefolded = word.casefold()
        node = self._root
        path = []

        for ch in casefolded:
            nxt = node.children.get(ch)
            if nxt is None:
                return False
            path.append((node, ch, nxt))
            node = nxt

        if node.word is None:
            return False

        node.word = None
        node.weight = None
        node.casefolded = None
        self._size -= 1

        while path:
            parent, ch, child = path[-1]
            if child.word is not None or child.children:
                break
            parent.children.pop(ch, None)
            path.pop()

        return True

    def __contains__(self, word: str) -> bool:
        node = self._node_for(word.casefold())
        return node is not None and node.word is not None

    def __len__(self) -> int:
        return self._size

    def complete(self, prefix: str, k: int = 10) -> list[str]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []

        node = self._node_for(prefix.casefold())
        if node is None:
            return []

        matches = []
        for term in self._iter_terminal_nodes(node):
            matches.append((term.weight, term.casefolded, term.word))

        matches.sort(key=lambda item: (-item[0], item[1]))
        return [word for _, _, word in matches[:k]]
