"""Binary search utilities."""

def first_index(a, x) -> int:
    n = len(a)
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    if lo < n and a[lo] == x:
        return lo
    return -1


def last_index(a, x) -> int:
    n = len(a)
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    idx = lo - 1
    if idx >= 0 and a[idx] == x:
        return idx
    return -1


def insertion_point(a, x) -> int:
    n = len(a)
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count(a, x) -> int:
    first = first_index(a, x)
    if first == -1:
        return 0
    last = last_index(a, x)
    if last == -1:
        return 0
    return last - first + 1


def rotation_offset(a) -> int:
    n = len(a)
    if n == 0:
        raise ValueError("a must not be empty")

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo


def search_rotated(a, x) -> int:
    n = len(a)
    if n == 0:
        return -1

    offset = rotation_offset(a)
    lo, hi = offset, offset + n - 1

    while lo <= hi:
        mid = (lo + hi) // 2
        idx = mid % n
        value = a[idx]

        if value == x:
            return idx
        if value < x:
            lo = mid + 1
        else:
            hi = mid - 1

    return -1


def isqrt(n: int) -> int:
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n

    x = 1 << ((n.bit_length() + 1) // 2)

    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y

    while x * x > n:
        x -= 1
    while (x + 1) * (x + 1) <= n:
        x += 1

    return x
