"""A small synchronous event emitter."""


class EmitError(Exception):
    """Raised when one or more event listeners fail."""

    def __init__(self, errors=None, message=None):
        self.errors = [] if errors is None else list(errors)
        if message is None:
            message = f"{len(self.errors)} listener error(s)"
        super().__init__(message)


class _Registration:
    __slots__ = ("listener", "once", "active")

    def __init__(self, listener, once):
        self.listener = listener
        self.once = once
        self.active = True


def _same_listener(stored, target):
    if stored is target:
        return True

    try:
        eq = stored == target
        if eq is not NotImplemented:
            return bool(eq)
    except Exception:
        pass

    try:
        eq = target == stored
        if eq is not NotImplemented:
            return bool(eq)
    except Exception:
        pass

    return False


class Emitter:
    def __init__(self):
        self._registrations = {}

    def on(self, event, listener):
        self._registrations.setdefault(event, []).append(
            _Registration(listener, False)
        )
        return listener

    def once(self, event, listener):
        self._registrations.setdefault(event, []).append(
            _Registration(listener, True)
        )
        return listener

    def off(self, event, listener=None):
        regs = self._registrations.get(event)
        if regs is None:
            return 0
        if not regs:
            del self._registrations[event]
            return 0

        if listener is None:
            for reg in regs:
                reg.active = False
            del self._registrations[event]
            return len(regs)

        for index, reg in enumerate(regs):
            if _same_listener(reg.listener, listener):
                reg.active = False
                del regs[index]
                if not regs:
                    del self._registrations[event]
                return 1

        return 0

    def listeners(self, event):
        return [reg.listener for reg in self._registrations.get(event, [])]

    def emit(self, event, *args, **kwargs):
        regs = self._registrations.get(event)
        if not regs:
            return 0

        snapshot = list(regs)
        calls = 0
        errors = []

        for reg in snapshot:
            if not reg.active:
                continue

            if reg.once:
                self._remove_registration(event, reg)

            calls += 1
            try:
                reg.listener(*args, **kwargs)
            except Exception as exc:
                errors.append((reg.listener, exc))

        if errors:
            raise EmitError(errors)

        return calls

    def _remove_registration(self, event, reg):
        if not reg.active:
            return

        regs = self._registrations.get(event)
        if regs is not None:
            for index, existing in enumerate(regs):
                if existing is reg:
                    del regs[index]
                    break
            if not regs:
                del self._registrations[event]

        reg.active = False
